export default [{"id":"3253","jozz":"20","page":"385","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"10","line_end":"10","aya_no":"1","aya_text":"طسٓمٓ","aya_text_emlaey":"طسم","aya_tafseer":"[1] طسٓمٓ سبق الكلام على الحروف المقطَّعة في أول سورة البقرة."},{"id":"3254","jozz":"20","page":"385","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"10","line_end":"10","aya_no":"2","aya_text":"تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡمُبِينِ","aya_text_emlaey":"تلك آيات الكتاب المبين","aya_tafseer":"[2] هذه آيات القرآن الذي أنزلته إليك -أيها الرسول-، مبيناً لكل ما يحتاج إليه العباد في دنياهم وأخراهم."},{"id":"3255","jozz":"20","page":"385","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"10","line_end":"11","aya_no":"3","aya_text":"نَتۡلُواْ عَلَيۡكَ مِن نَّبَإِ مُوسَىٰ وَفِرۡعَوۡنَ بِٱلۡحَقِّ لِقَوۡمٖ يُؤۡمِنُونَ","aya_text_emlaey":"نتلوا عليك من نبإ موسى وفرعون بالحق لقوم يؤمنون","aya_tafseer":"[3] نقصُّ عليك من خبر موسى وفرعون بالصدق لقوم يؤمنون بهذا القرآن، ويصدِّقون بأنه من عند الله، ويعملون بهديه."},{"id":"3256","jozz":"20","page":"385","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"11","line_end":"14","aya_no":"4","aya_text":"إِنَّ فِرۡعَوۡنَ عَلَا فِي ٱلۡأَرۡضِ وَجَعَلَ أَهۡلَهَا شِيَعٗا يَسۡتَضۡعِفُ طَآئِفَةٗ مِّنۡهُمۡ يُذَبِّحُ أَبۡنَآءَهُمۡ وَيَسۡتَحۡيِۦ نِسَآءَهُمۡۚ إِنَّهُۥ كَانَ مِنَ ٱلۡمُفۡسِدِينَ","aya_text_emlaey":"إن فرعون علا في الأرض وجعل أهلها شيعا يستضعف طائفة منهم يذبح أبناءهم ويستحيي نساءهم إنه كان من المفسدين","aya_tafseer":"[4] إن فرعون تكبر وطغى في الأرض، وجعل أهلها طوائف متفرقة، يستضعف طائفة منهم، وهم بنو إسرائيل، يذبِّح أبناءهم، ويستبقي نساءهم؛ للخدمة والامتهان، إنه كان من المفسدين في الأرض."},{"id":"3257","jozz":"20","page":"385","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"14","line_end":"15","aya_no":"5","aya_text":"وَنُرِيدُ أَن نَّمُنَّ عَلَى ٱلَّذِينَ ٱسۡتُضۡعِفُواْ فِي ٱلۡأَرۡضِ وَنَجۡعَلَهُمۡ أَئِمَّةٗ وَنَجۡعَلَهُمُ ٱلۡوَٰرِثِينَ","aya_text_emlaey":"ونريد أن نمن على الذين استضعفوا في الأرض ونجعلهم أئمة ونجعلهم الوارثين","aya_tafseer":"[5] ونريد أن نتفضل على الذين استضعفهم فرعون في الأرض، ونجعلهم قادةً في الخير ودعاةً إليه، ونجعلهم يرثون الأرض بعد هلاك فرعون وقومه."},{"id":"3258","jozz":"20","page":"386","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"1","line_end":"2","aya_no":"6","aya_text":"وَنُمَكِّنَ لَهُمۡ فِي ٱلۡأَرۡضِ وَنُرِيَ فِرۡعَوۡنَ وَهَٰمَٰنَ وَجُنُودَهُمَا مِنۡهُم مَّا كَانُواْ يَحۡذَرُونَ","aya_text_emlaey":"ونمكن لهم في الأرض ونري فرعون وهامان وجنودهما منهم ما كانوا يحذرون","aya_tafseer":"[6] ونمكن لهم في الأرض، ونجعل فرعون وهامان وجنودهما يرون من هذه الطائفة المستضعفة ما كانوا يخافونه مِن هلاكهم وذهاب ملكهم، وإخراجهم من ديارهم على يد مولود من بني إسرائيل."},{"id":"3259","jozz":"20","page":"386","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"2","line_end":"4","aya_no":"7","aya_text":"وَأَوۡحَيۡنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنۡ أَرۡضِعِيهِۖ فَإِذَا خِفۡتِ عَلَيۡهِ فَأَلۡقِيهِ فِي ٱلۡيَمِّ وَلَا تَخَافِي وَلَا تَحۡزَنِيٓۖ إِنَّا رَآدُّوهُ إِلَيۡكِ وَجَاعِلُوهُ مِنَ ٱلۡمُرۡسَلِينَ","aya_text_emlaey":"وأوحينا إلى أم موسى أن أرضعيه فإذا خفت عليه فألقيه في اليم ولا تخافي ولا تحزني إنا رادوه إليك وجاعلوه من المرسلين","aya_tafseer":"[7] وألْهمنا أم موسى حين ولدته وخشيت عليه أن يذبحه فرعون كما يذبح أبناء بني إسرائيل: أن أرضعيه مطمئنة، فإذا خشيت أن يُعرف أمره فضعيه في صندوق وألقيه في النيل، دون خوف من فرعون وقومه أن يقتلوه، ودون حزن على فراقه، إنا رادُّو ولدك إليك وباعثوه رسولاً"},{"id":"3260","jozz":"20","page":"386","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"5","line_end":"6","aya_no":"8","aya_text":"فَٱلۡتَقَطَهُۥٓ ءَالُ فِرۡعَوۡنَ لِيَكُونَ لَهُمۡ عَدُوّٗا وَحَزَنًاۗ إِنَّ فِرۡعَوۡنَ وَهَٰمَٰنَ وَجُنُودَهُمَا كَانُواْ خَٰطِـِٔينَ","aya_text_emlaey":"فالتقطه آل فرعون ليكون لهم عدوا وحزنا إن فرعون وهامان وجنودهما كانوا خاطئين","aya_tafseer":"[8] فوضعته في صندوق وألقته في النيل، فعثر عليه أعوان فرعون وأخذوه، فكانت عاقبةُ ذلك ما قَدَّره الله بأن يكون موسى عدوّاً لهم بمخالفة دينهم، وموقعاً لهم في الحزن بإغراقهم وزوال مُلْكهم على يده. إن فرعون وهامان وأعوانهما كانوا آثمين مشركين."},{"id":"3261","jozz":"20","page":"386","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"7","line_end":"8","aya_no":"9","aya_text":"وَقَالَتِ ٱمۡرَأَتُ فِرۡعَوۡنَ قُرَّتُ عَيۡنٖ لِّي وَلَكَۖ لَا تَقۡتُلُوهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدٗا وَهُمۡ لَا يَشۡعُرُونَ","aya_text_emlaey":"وقالت امرأة فرعون قرة عين لي ولك لا تقتلوه عسى أن ينفعنا أو نتخذه ولدا وهم لا يشعرون","aya_tafseer":"[9] ولمَّا شاهدته امرأة فرعون ألقى الله محبته في قلبها، وقالت لفرعون: هذا الطفل سيكون مصدر سرور لي ولك، لا تقتلوه؛ فقد نصيب منه خيراً أو نتخذه ولداً، وفرعون وآله لا يدركون أن هلاكهم على يديه."},{"id":"3262","jozz":"20","page":"386","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"9","line_end":"10","aya_no":"10","aya_text":"وَأَصۡبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَٰرِغًاۖ إِن كَادَتۡ لَتُبۡدِي بِهِۦ لَوۡلَآ أَن رَّبَطۡنَا عَلَىٰ قَلۡبِهَا لِتَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"وأصبح فؤاد أم موسى فارغا إن كادت لتبدي به لولا أن ربطنا على قلبها لتكون من المؤمنين","aya_tafseer":"[10] وأصبح فؤاد أم موسى خالياً من كل شيء في الدنيا إلا من همِّ موسى وذكره، وقاربت أن تُظهِر أنه ابنها لولا أن ثبتناها، فصبرت ولم تُبْدِ به؛ لتكون من المؤمنين بوعد الله الموقنين به."},{"id":"3263","jozz":"20","page":"386","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"10","line_end":"11","aya_no":"11","aya_text":"وَقَالَتۡ لِأُخۡتِهِۦ قُصِّيهِۖ فَبَصُرَتۡ بِهِۦ عَن جُنُبٖ وَهُمۡ لَا يَشۡعُرُونَ","aya_text_emlaey":"وقالت لأخته قصيه فبصرت به عن جنب وهم لا يشعرون","aya_tafseer":"[11] وقالت أم موسى لأخته حين ألقته في اليم: اتَّبِعي أثر موسى كيف يُصْنَع به؟ فتتبعت أثره فأبصرته عن بُعْد، وقوم فرعون لا يعرفون أنها أخته، وأنها تتبع خبره."},{"id":"3264","jozz":"20","page":"386","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"12","line_end":"13","aya_no":"12","aya_text":"۞ وَحَرَّمۡنَا عَلَيۡهِ ٱلۡمَرَاضِعَ مِن قَبۡلُ فَقَالَتۡ هَلۡ أَدُلُّكُمۡ عَلَىٰٓ أَهۡلِ بَيۡتٖ يَكۡفُلُونَهُۥ لَكُمۡ وَهُمۡ لَهُۥ نَٰصِحُونَ","aya_text_emlaey":"وحرمنا عليه المراضع من قبل فقالت هل أدلكم على أهل بيت يكفلونه لكم وهم له ناصحون","aya_tafseer":"[12] وحرَّمنا على موسى المراضع أن يرتضع منهن مِن قبل أن نردَّه إلى أمه، فقالت أخته: هل أدلكم على أهل بيت يحسنون تربيته وإرضاعه، وهم مشفقون عليه؟ فأجابوها إلى ذلك."},{"id":"3265","jozz":"20","page":"386","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"14","line_end":"15","aya_no":"13","aya_text":"فَرَدَدۡنَٰهُ إِلَىٰٓ أُمِّهِۦ كَيۡ تَقَرَّ عَيۡنُهَا وَلَا تَحۡزَنَ وَلِتَعۡلَمَ أَنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ","aya_text_emlaey":"فرددناه إلى أمه كي تقر عينها ولا تحزن ولتعلم أن وعد الله حق ولكن أكثرهم لا يعلمون","aya_tafseer":"[13] فرددنا موسى إلى أمه؛ كي تَقَرَّ عينها به، ووفينا لها بالوعد؛ إذ رجع إليها سليماً مِن قتل فرعون، ولا تحزنَ على فراقه، ولتعلم أن وعد الله حق فيما وعدها مِن ردِّه إليها وجعله من المرسلين. إن الله لا يخلف وعده، ولكن أكثر المشركين لا يعلمون أن وعد الله حق."},{"id":"3266","jozz":"20","page":"387","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"1","line_end":"2","aya_no":"14","aya_text":"وَلَمَّا بَلَغَ أَشُدَّهُۥ وَٱسۡتَوَىٰٓ ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ","aya_text_emlaey":"ولما بلغ أشده واستوى آتيناه حكما وعلما وكذلك نجزي المحسنين","aya_tafseer":"[14] ولما بلغ موسى أشد قوته وتكامل عقله، آتيناه حكماً وعلماً يعرف بهما الأحكام الشرعية، وكما جزينا موسى على طاعته وإحسانه نجزي مَن أحسن مِن عبادنا."},{"id":"3267","jozz":"20","page":"387","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"2","line_end":"6","aya_no":"15","aya_text":"وَدَخَلَ ٱلۡمَدِينَةَ عَلَىٰ حِينِ غَفۡلَةٖ مِّنۡ أَهۡلِهَا فَوَجَدَ فِيهَا رَجُلَيۡنِ يَقۡتَتِلَانِ هَٰذَا مِن شِيعَتِهِۦ وَهَٰذَا مِنۡ عَدُوِّهِۦۖ فَٱسۡتَغَٰثَهُ ٱلَّذِي مِن شِيعَتِهِۦ عَلَى ٱلَّذِي مِنۡ عَدُوِّهِۦ فَوَكَزَهُۥ مُوسَىٰ فَقَضَىٰ عَلَيۡهِۖ قَالَ هَٰذَا مِنۡ عَمَلِ ٱلشَّيۡطَٰنِۖ إِنَّهُۥ عَدُوّٞ مُّضِلّٞ مُّبِينٞ","aya_text_emlaey":"ودخل المدينة على حين غفلة من أهلها فوجد فيها رجلين يقتتلان هذا من شيعته وهذا من عدوه فاستغاثه الذي من شيعته على الذي من عدوه فوكزه موسى فقضى عليه قال هذا من عمل الشيطان إنه عدو مضل مبين","aya_tafseer":"[15] ودخل موسى المدينة مستخفياً وقت غفلة أهلها، فوجد فيها رجلين يقتتلان: أحدهما من قوم موسى من بني إسرائيل، والآخر من قوم فرعون، فطلب الذي من قوم موسى النصر على الذي من عدوه، فضربه موسى بجُمْع كفِّه فمات، قال موسى حين قتله: هذا من نزغ الشيطان، بأن هيَّج غضبي، حتى ضربت هذا فهلك، إن الشيطان عدو لابن آدم، مضل عن سبيل الرشاد، ظاهر العداوة. وهذا العمل من موسى عليه السلام كان قبل النبوة."},{"id":"3268","jozz":"20","page":"387","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"6","line_end":"7","aya_no":"16","aya_text":"قَالَ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي فَٱغۡفِرۡ لِي فَغَفَرَ لَهُۥٓۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ","aya_text_emlaey":"قال رب إني ظلمت نفسي فاغفر لي فغفر له إنه هو الغفور الرحيم","aya_tafseer":"[16] قال موسى: ربِّ إني ظلمت نفسي بقتل النفس التي لم تأمرني بقتلها فاغفر لي ذلك الذنب، فغفر الله له. إن الله غفور لذنوب عباده، رحيم بهم."},{"id":"3269","jozz":"20","page":"387","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"7","line_end":"8","aya_no":"17","aya_text":"قَالَ رَبِّ بِمَآ أَنۡعَمۡتَ عَلَيَّ فَلَنۡ أَكُونَ ظَهِيرٗا لِّلۡمُجۡرِمِينَ","aya_text_emlaey":"قال رب بما أنعمت علي فلن أكون ظهيرا للمجرمين","aya_tafseer":"[17] قال موسى: ربِّ بما أنعمت عليَّ بالتوبة والمغفرة والنعم الكثيرة، فلن أكون معيناً لأحد على معصيته وإجرامه."},{"id":"3270","jozz":"20","page":"387","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"8","line_end":"10","aya_no":"18","aya_text":"فَأَصۡبَحَ فِي ٱلۡمَدِينَةِ خَآئِفٗا يَتَرَقَّبُ فَإِذَا ٱلَّذِي ٱسۡتَنصَرَهُۥ بِٱلۡأَمۡسِ يَسۡتَصۡرِخُهُۥۚ قَالَ لَهُۥ مُوسَىٰٓ إِنَّكَ لَغَوِيّٞ مُّبِينٞ","aya_text_emlaey":"فأصبح في المدينة خائفا يترقب فإذا الذي استنصره بالأمس يستصرخه قال له موسى إنك لغوي مبين","aya_tafseer":"[18] فأصبح موسى في مدينة فرعون خائفاً يترقب الأخبار مما يتحدث به الناس في أمره وأمر قتيله، فرأى صاحبَه بالأمس يقاتل قبطياً آخر، ويطلب منه النصر، قال له موسى: إنك لكثير الغَواية ظاهر الضلال."},{"id":"3271","jozz":"20","page":"387","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"10","line_end":"13","aya_no":"19","aya_text":"فَلَمَّآ أَنۡ أَرَادَ أَن يَبۡطِشَ بِٱلَّذِي هُوَ عَدُوّٞ لَّهُمَا قَالَ يَٰمُوسَىٰٓ أَتُرِيدُ أَن تَقۡتُلَنِي كَمَا قَتَلۡتَ نَفۡسَۢا بِٱلۡأَمۡسِۖ إِن تُرِيدُ إِلَّآ أَن تَكُونَ جَبَّارٗا فِي ٱلۡأَرۡضِ وَمَا تُرِيدُ أَن تَكُونَ مِنَ ٱلۡمُصۡلِحِينَ","aya_text_emlaey":"فلما أن أراد أن يبطش بالذي هو عدو لهما قال ياموسى أتريد أن تقتلني كما قتلت نفسا بالأمس إن تريد إلا أن تكون جبارا في الأرض وما تريد أن تكون من المصلحين","aya_tafseer":"[19] فلما أن أراد موسى أن يبطش بالقبطي، قال: يا موسى أتريد أن تقتلني كما قتلت نفساً بالأمس؟ ما تريد إلا أن تكون طاغية في الأرض، وما تريد أن تكون من الذين يصلحون بين الناس."},{"id":"3272","jozz":"20","page":"387","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"13","line_end":"14","aya_no":"20","aya_text":"وَجَآءَ رَجُلٞ مِّنۡ أَقۡصَا ٱلۡمَدِينَةِ يَسۡعَىٰ قَالَ يَٰمُوسَىٰٓ إِنَّ ٱلۡمَلَأَ يَأۡتَمِرُونَ بِكَ لِيَقۡتُلُوكَ فَٱخۡرُجۡ إِنِّي لَكَ مِنَ ٱلنَّٰصِحِينَ","aya_text_emlaey":"وجاء رجل من أقصى المدينة يسعى قال ياموسى إن الملأ يأتمرون بك ليقتلوك فاخرج إني لك من الناصحين","aya_tafseer":"[20] وجاء رجل من آخر المدينة يسعى، قال يا موسى: إن أشراف قوم فرعون يتآمرون على قتلك ويتشاورون، فاخرج من هذه المدينة، إني لك من الناصحين المشفقين عليك."},{"id":"3273","jozz":"20","page":"387","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"15","line_end":"15","aya_no":"21","aya_text":"فَخَرَجَ مِنۡهَا خَآئِفٗا يَتَرَقَّبُۖ قَالَ رَبِّ نَجِّنِي مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ","aya_text_emlaey":"فخرج منها خائفا يترقب قال رب نجني من القوم الظالمين","aya_tafseer":"[21] فخرج موسى من مدينة فرعون خائفاً ينتظر الطلب أن يدركه فيأخذه، فدعا الله أن ينقذه من القوم الظالمين."},{"id":"3274","jozz":"20","page":"388","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"1","line_end":"2","aya_no":"22","aya_text":"وَلَمَّا تَوَجَّهَ تِلۡقَآءَ مَدۡيَنَ قَالَ عَسَىٰ رَبِّيٓ أَن يَهۡدِيَنِي سَوَآءَ ٱلسَّبِيلِ","aya_text_emlaey":"ولما توجه تلقاء مدين قال عسى ربي أن يهديني سواء السبيل","aya_tafseer":"[22] ولما قصد موسى بلاد «مدين» وخرج من سلطان فرعون قال: عسى ربي أن يرشدني خير طريق إلى «مدين»."},{"id":"3275","jozz":"20","page":"388","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"2","line_end":"5","aya_no":"23","aya_text":"وَلَمَّا وَرَدَ مَآءَ مَدۡيَنَ وَجَدَ عَلَيۡهِ أُمَّةٗ مِّنَ ٱلنَّاسِ يَسۡقُونَ وَوَجَدَ مِن دُونِهِمُ ٱمۡرَأَتَيۡنِ تَذُودَانِۖ قَالَ مَا خَطۡبُكُمَاۖ قَالَتَا لَا نَسۡقِي حَتَّىٰ يُصۡدِرَ ٱلرِّعَآءُۖ وَأَبُونَا شَيۡخٞ كَبِيرٞ","aya_text_emlaey":"ولما ورد ماء مدين وجد عليه أمة من الناس يسقون ووجد من دونهم امرأتين تذودان قال ما خطبكما قالتا لا نسقي حتى يصدر الرعاء وأبونا شيخ كبير","aya_tafseer":"[23] ولما وصل ماء «مدين» وجد عليه جماعة من الناس يسقون مواشيهم، ووجد من دون تلك الجماعة امرأتين منفردتين عن الناس، تحبسان غنمهما عن الماء؛ لعجزهما وضعفهما عن مزاحمة الرجال، وتنتظران حتى تَصْدُر عنه مواشي الناس، ثم تسقيان ماشيتهما، فلما رآهما موسى -عليه السلام- رقَّ لهما، ثم قال: ما شأنكما؟ قالتا: لا نستطيع مزاحمة الرجال، ولا نسقي حتى يسقي الناس، وأبونا شيخ كبير، لا يستطيع أن يسقي ماشيته؛ لضعفه وكبره."},{"id":"3276","jozz":"20","page":"388","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"5","line_end":"6","aya_no":"24","aya_text":"فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰٓ إِلَى ٱلظِّلِّ فَقَالَ رَبِّ إِنِّي لِمَآ أَنزَلۡتَ إِلَيَّ مِنۡ خَيۡرٖ فَقِيرٞ","aya_text_emlaey":"فسقى لهما ثم تولى إلى الظل فقال رب إني لما أنـزلت إلي من خير فقير","aya_tafseer":"[24] فسقى موسى للمرأتين ماشيتهما، ثم تولى إلى ظل شجرة فاستظلَّ بها وقال: ربِّ إني مفتقر إلى ما تسوقه إليَّ مِن أي خير كان، كالطعام. وكان قد اشتد به الجوع."},{"id":"3277","jozz":"20","page":"388","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"6","line_end":"9","aya_no":"25","aya_text":"فَجَآءَتۡهُ إِحۡدَىٰهُمَا تَمۡشِي عَلَى ٱسۡتِحۡيَآءٖ قَالَتۡ إِنَّ أَبِي يَدۡعُوكَ لِيَجۡزِيَكَ أَجۡرَ مَا سَقَيۡتَ لَنَاۚ فَلَمَّا جَآءَهُۥ وَقَصَّ عَلَيۡهِ ٱلۡقَصَصَ قَالَ لَا تَخَفۡۖ نَجَوۡتَ مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ","aya_text_emlaey":"فجاءته إحداهما تمشي على استحياء قالت إن أبي يدعوك ليجزيك أجر ما سقيت لنا فلما جاءه وقص عليه القصص قال لا تخف نجوت من القوم الظالمين","aya_tafseer":"[25] فجاءت إحدى المرأتين اللتين سقى لهما تسير إليه في حياء، قالت: إن أبي يدعوك ليعطيك أجر ما سقيت لنا، فمضى موسى معها إلى أبيها، فلما جاء أباها وقَصَّ عليه قصصه مع فرعون وقومه، قال له أبوها: لا تَخَفْ نجوت من القوم الظالمين، وهم فرعون وقومه؛ إذ لا سلطان لهم بأرضنا."},{"id":"3278","jozz":"20","page":"388","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"9","line_end":"10","aya_no":"26","aya_text":"قَالَتۡ إِحۡدَىٰهُمَا يَٰٓأَبَتِ ٱسۡتَـٔۡجِرۡهُۖ إِنَّ خَيۡرَ مَنِ ٱسۡتَـٔۡجَرۡتَ ٱلۡقَوِيُّ ٱلۡأَمِينُ","aya_text_emlaey":"قالت إحداهما ياأبت استأجره إن خير من استأجرت القوي الأمين","aya_tafseer":"[26] قالت إحدى المرأتين لأبيها: يا أبت استأجره ليرعى لك ماشيتك؛ إنَّ خير من تستأجره للرعي القوي على حفظ ماشيتك، الأمين الذي لا تخاف خيانته فيما تأمنه عليه."},{"id":"3279","jozz":"20","page":"388","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"11","line_end":"14","aya_no":"27","aya_text":"قَالَ إِنِّيٓ أُرِيدُ أَنۡ أُنكِحَكَ إِحۡدَى ٱبۡنَتَيَّ هَٰتَيۡنِ عَلَىٰٓ أَن تَأۡجُرَنِي ثَمَٰنِيَ حِجَجٖۖ فَإِنۡ أَتۡمَمۡتَ عَشۡرٗا فَمِنۡ عِندِكَۖ وَمَآ أُرِيدُ أَنۡ أَشُقَّ عَلَيۡكَۚ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰلِحِينَ","aya_text_emlaey":"قال إني أريد أن أنكحك إحدى ابنتي هاتين على أن تأجرني ثماني حجج فإن أتممت عشرا فمن عندك وما أريد أن أشق عليك ستجدني إن شاء الله من الصالحين","aya_tafseer":"[27] قال الشيخ لموسى: إني أريد أن أزوِّجك إحدى ابنتيَّ هاتين، على أن تكون أجيراً لي في رعي ماشيتي ثماني سنين مقابل ذلك، فإن أكملت عشر سنين فإحسان من عندك، وما أريد أن أشق عليك بجعلها عشراً، ستجدني إن شاء الله من الصالحين في حسن الصحبة والوفاء بما قلتُ."},{"id":"3280","jozz":"20","page":"388","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"14","line_end":"15","aya_no":"28","aya_text":"قَالَ ذَٰلِكَ بَيۡنِي وَبَيۡنَكَۖ أَيَّمَا ٱلۡأَجَلَيۡنِ قَضَيۡتُ فَلَا عُدۡوَٰنَ عَلَيَّۖ وَٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٞ","aya_text_emlaey":"قال ذلك بيني وبينك أيما الأجلين قضيت فلا عدوان علي والله على ما نقول وكيل","aya_tafseer":"[28] قال موسى: ذلك الذي قلتَه قائم بيني وبينك، أي المدتين أَقْضِها في العمل أكن قد وفيتك، فلا أُطالَب بزيادة عليها، والله على ما نقول وكيل حافظ يراقبنا، ويعلم ما تعاقدنا عليه."},{"id":"3281","jozz":"20","page":"389","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"1","line_end":"3","aya_no":"29","aya_text":"۞ فَلَمَّا قَضَىٰ مُوسَى ٱلۡأَجَلَ وَسَارَ بِأَهۡلِهِۦٓ ءَانَسَ مِن جَانِبِ ٱلطُّورِ نَارٗاۖ قَالَ لِأَهۡلِهِ ٱمۡكُثُوٓاْ إِنِّيٓ ءَانَسۡتُ نَارٗا لَّعَلِّيٓ ءَاتِيكُم مِّنۡهَا بِخَبَرٍ أَوۡ جَذۡوَةٖ مِّنَ ٱلنَّارِ لَعَلَّكُمۡ تَصۡطَلُونَ","aya_text_emlaey":"فلما قضى موسى الأجل وسار بأهله آنس من جانب الطور نارا قال لأهله امكثوا إني آنست نارا لعلي آتيكم منها بخبر أو جذوة من النار لعلكم تصطلون","aya_tafseer":"[29] فلما وفَّى نبي الله موسى -عليه السلام- صاحبَه المدة عشر سنين -وهي أكمل المدتين- وسار بأهله إلى «مصر» أبصر من جانب الطور ناراً، قال موسى لأهله: تمهلوا وانتظروا إني أبصرت ناراً؛ لعلي آتيكم منها بنبأ، أو آتيكم بشعلة من النار لعلكم تستدفئون بها."},{"id":"3282","jozz":"20","page":"389","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"4","line_end":"6","aya_no":"30","aya_text":"فَلَمَّآ أَتَىٰهَا نُودِيَ مِن شَٰطِيِٕ ٱلۡوَادِ ٱلۡأَيۡمَنِ فِي ٱلۡبُقۡعَةِ ٱلۡمُبَٰرَكَةِ مِنَ ٱلشَّجَرَةِ أَن يَٰمُوسَىٰٓ إِنِّيٓ أَنَا ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"فلما أتاها نودي من شاطئ الواد الأيمن في البقعة المباركة من الشجرة أن ياموسى إني أنا الله رب العالمين","aya_tafseer":"[30] فلما أتى موسى النار ناداه الله من جانب الوادي الأيمن لموسى في البقعة المباركة من جانب الشجرة: أن يا موسى إني أنا الله رب العالمين،"},{"id":"3283","jozz":"20","page":"389","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"6","line_end":"8","aya_no":"31","aya_text":"وَأَنۡ أَلۡقِ عَصَاكَۚ فَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا جَآنّٞ وَلَّىٰ مُدۡبِرٗا وَلَمۡ يُعَقِّبۡۚ يَٰمُوسَىٰٓ أَقۡبِلۡ وَلَا تَخَفۡۖ إِنَّكَ مِنَ ٱلۡأٓمِنِينَ","aya_text_emlaey":"وأن ألق عصاك فلما رآها تهتز كأنها جان ولى مدبرا ولم يعقب ياموسى أقبل ولا تخف إنك من الآمنين","aya_tafseer":"[31] وأن ألق عصاك، فألقاها موسى، فصارت حية تسعى، فلما رآها موسى تضطرب كأنها جانٌّ من الحيات ولَّى هارباً منها، ولم يلتفت من الخوف، فناداه ربه: يا موسى أقبل إليَّ ولا تَخَفْ؛ إنك من الآمنين من كل مكروه."},{"id":"3284","jozz":"20","page":"389","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"8","line_end":"11","aya_no":"32","aya_text":"ٱسۡلُكۡ يَدَكَ فِي جَيۡبِكَ تَخۡرُجۡ بَيۡضَآءَ مِنۡ غَيۡرِ سُوٓءٖ وَٱضۡمُمۡ إِلَيۡكَ جَنَاحَكَ مِنَ ٱلرَّهۡبِۖ فَذَٰنِكَ بُرۡهَٰنَانِ مِن رَّبِّكَ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦٓۚ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ","aya_text_emlaey":"اسلك يدك في جيبك تخرج بيضاء من غير سوء واضمم إليك جناحك من الرهب فذانك برهانان من ربك إلى فرعون وملئه إنهم كانوا قوما فاسقين","aya_tafseer":"[32] أدخل يدك في فتحة قميصك المفتوحة إلى الصَّدر، وأخرِجْها تخرج بيضاء كالثلج مِن غير مرض ولا برص، واضمم إليك يدك لتأمن من الخوف، فهاتان اللتان أريتُكَهما يا موسى: مِن تحوُّل العصا حية، وجَعْلِ يدك بيضاء تلمع من غير مرض ولا برص، آيتان من ربك إلى فرعون وأشراف قومه. إن فرعون وملأه كانوا قوماً كافرين."},{"id":"3285","jozz":"20","page":"389","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"11","line_end":"12","aya_no":"33","aya_text":"قَالَ رَبِّ إِنِّي قَتَلۡتُ مِنۡهُمۡ نَفۡسٗا فَأَخَافُ أَن يَقۡتُلُونِ","aya_text_emlaey":"قال رب إني قتلت منهم نفسا فأخاف أن يقتلون","aya_tafseer":"[33، 34] قال موسى: ربِّ إني قتلت من قوم فرعون نفساً فأخاف أن يقتلوني، وأخي هارون هو أفصح مني نطقاً، فأرسله معي عوناً يصدقني، ويبين لهم عني ما أخاطبهم به، إني أخاف أن يكذبوني في قولي لهم: إني أُرسلت إليهم."},{"id":"3286","jozz":"20","page":"389","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"12","line_end":"13","aya_no":"34","aya_text":"وَأَخِي هَٰرُونُ هُوَ أَفۡصَحُ مِنِّي لِسَانٗا فَأَرۡسِلۡهُ مَعِيَ رِدۡءٗا يُصَدِّقُنِيٓۖ إِنِّيٓ أَخَافُ أَن يُكَذِّبُونِ","aya_text_emlaey":"وأخي هارون هو أفصح مني لسانا فأرسله معي ردءا يصدقني إني أخاف أن يكذبون","aya_tafseer":"[33، 34] قال موسى: ربِّ إني قتلت من قوم فرعون نفساً فأخاف أن يقتلوني، وأخي هارون هو أفصح مني نطقاً، فأرسله معي عوناً يصدقني، ويبين لهم عني ما أخاطبهم به، إني أخاف أن يكذبوني في قولي لهم: إني أُرسلت إليهم."},{"id":"3287","jozz":"20","page":"389","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"14","line_end":"15","aya_no":"35","aya_text":"قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجۡعَلُ لَكُمَا سُلۡطَٰنٗا فَلَا يَصِلُونَ إِلَيۡكُمَا بِـَٔايَٰتِنَآۚ أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلۡغَٰلِبُونَ","aya_text_emlaey":"قال سنشد عضدك بأخيك ونجعل لكما سلطانا فلا يصلون إليكما بآياتنا أنتما ومن اتبعكما الغالبون","aya_tafseer":"[35] قال الله لموسى: سنقوِّيك بأخيك، ونجعل لكما حجة على فرعون وقومه فلا يصلون إليكما بسوء. أنتما -يا موسى وهارون- ومَن آمن بكما المنتصرون على فرعون وقومه؛ بسبب آياتنا وما دلَّتْ عليه من الحق."},{"id":"3288","jozz":"20","page":"390","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"1","line_end":"2","aya_no":"36","aya_text":"فَلَمَّا جَآءَهُم مُّوسَىٰ بِـَٔايَٰتِنَا بَيِّنَٰتٖ قَالُواْ مَا هَٰذَآ إِلَّا سِحۡرٞ مُّفۡتَرٗى وَمَا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا ٱلۡأَوَّلِينَ","aya_text_emlaey":"فلما جاءهم موسى بآياتنا بينات قالوا ما هذا إلا سحر مفترى وما سمعنا بهذا في آبائنا الأولين","aya_tafseer":"[36] فلما جاء موسى فرعونَ وملأه بأدلتنا وحججنا شاهدة بحقيقة ما جاء به موسى مِن عند ربه، قالوا لموسى: ما هذا الذي جئتنا به إلا سحر افتريته كذباً وباطلاً، وما سمعنا بهذا الذي تدعونا إليه في أسلافنا الذين مضَوا قبلنا."},{"id":"3289","jozz":"20","page":"390","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"3","line_end":"4","aya_no":"37","aya_text":"وَقَالَ مُوسَىٰ رَبِّيٓ أَعۡلَمُ بِمَن جَآءَ بِٱلۡهُدَىٰ مِنۡ عِندِهِۦ وَمَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّٰلِمُونَ","aya_text_emlaey":"وقال موسى ربي أعلم بمن جاء بالهدى من عنده ومن تكون له عاقبة الدار إنه لا يفلح الظالمون","aya_tafseer":"[37] وقال موسى لفرعون: ربي أعلم بالمحقِّ منَّا الذي جاء بالرشاد من عنده، ومَن الذي له العقبى المحمودة في الدار الآخرة، إنه لا يظفر الظالمون بمطلوبهم."},{"id":"3290","jozz":"20","page":"390","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"5","line_end":"7","aya_no":"38","aya_text":"وَقَالَ فِرۡعَوۡنُ يَٰٓأَيُّهَا ٱلۡمَلَأُ مَا عَلِمۡتُ لَكُم مِّنۡ إِلَٰهٍ غَيۡرِي فَأَوۡقِدۡ لِي يَٰهَٰمَٰنُ عَلَى ٱلطِّينِ فَٱجۡعَل لِّي صَرۡحٗا لَّعَلِّيٓ أَطَّلِعُ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُۥ مِنَ ٱلۡكَٰذِبِينَ","aya_text_emlaey":"وقال فرعون ياأيها الملأ ما علمت لكم من إله غيري فأوقد لي ياهامان على الطين فاجعل لي صرحا لعلي أطلع إلى إله موسى وإني لأظنه من الكاذبين","aya_tafseer":"[38] وقال فرعون لأشراف قومه: يا أيها الملأ ما علمت لكم من إله غيري يستحق العبادة، فأشْعِل لي -يا هامان- على الطين ناراً، حتى يشتد، وابْنِ لي بناء عالياً؛ لعلي أنظر إلى معبود موسى الذي يعبده ويدعو إلى عبادته، وإني لأظنه فيما يقول من الكاذبين."},{"id":"3291","jozz":"20","page":"390","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"8","line_end":"9","aya_no":"39","aya_text":"وَٱسۡتَكۡبَرَ هُوَ وَجُنُودُهُۥ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَظَنُّوٓاْ أَنَّهُمۡ إِلَيۡنَا لَا يُرۡجَعُونَ","aya_text_emlaey":"واستكبر هو وجنوده في الأرض بغير الحق وظنوا أنهم إلينا لا يرجعون","aya_tafseer":"[39] واستعلى فرعون وجنوده في أرض «مصر» بغير الحق عن تصديق موسى واتِّباعه على ما دعاهم إليه، وحسبوا أنهم بعد مماتهم لا يبعثون."},{"id":"3292","jozz":"20","page":"390","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"9","line_end":"10","aya_no":"40","aya_text":"فَأَخَذۡنَٰهُ وَجُنُودَهُۥ فَنَبَذۡنَٰهُمۡ فِي ٱلۡيَمِّۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ","aya_text_emlaey":"فأخذناه وجنوده فنبذناهم في اليم فانظر كيف كان عاقبة الظالمين","aya_tafseer":"[40] فأخذنا فرعون وجنوده، فألقيناهم جميعاً في البحر وأغرقناهم، فانظر -أيها الرسول- كيف كان نهاية هؤلاء الذين ظلموا أنفسهم، فكفروا بربهم؟"},{"id":"3293","jozz":"20","page":"390","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"11","line_end":"12","aya_no":"41","aya_text":"وَجَعَلۡنَٰهُمۡ أَئِمَّةٗ يَدۡعُونَ إِلَى ٱلنَّارِۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ لَا يُنصَرُونَ","aya_text_emlaey":"وجعلناهم أئمة يدعون إلى النار ويوم القيامة لا ينصرون","aya_tafseer":"[41] وجعلنا فرعون وقومه قادة إلى النار، يَقتدي بهم أهل الكفر والفسق، ويوم القيامة لا ينصرون؛ وذلك بسبب كفرهم وتكذيبهم رسول ربهم وإصرارهم على ذلك."},{"id":"3294","jozz":"20","page":"390","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"12","line_end":"13","aya_no":"42","aya_text":"وَأَتۡبَعۡنَٰهُمۡ فِي هَٰذِهِ ٱلدُّنۡيَا لَعۡنَةٗۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ هُم مِّنَ ٱلۡمَقۡبُوحِينَ","aya_text_emlaey":"وأتبعناهم في هذه الدنيا لعنة ويوم القيامة هم من المقبوحين","aya_tafseer":"[42] وأتبعنا فرعون وقومه في هذه الدنيا خزياً وغضباً منا عليهم، ويوم القيامة هم من المستقذرة أفعالهم، المبعدين عن رحمة الله."},{"id":"3295","jozz":"20","page":"390","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"13","line_end":"15","aya_no":"43","aya_text":"وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ مِنۢ بَعۡدِ مَآ أَهۡلَكۡنَا ٱلۡقُرُونَ ٱلۡأُولَىٰ بَصَآئِرَ لِلنَّاسِ وَهُدٗى وَرَحۡمَةٗ لَّعَلَّهُمۡ يَتَذَكَّرُونَ","aya_text_emlaey":"ولقد آتينا موسى الكتاب من بعد ما أهلكنا القرون الأولى بصائر للناس وهدى ورحمة لعلهم يتذكرون","aya_tafseer":"[43] ولقد آتينا موسى التوراة من بعد ما أهلكنا الأمم التي كانت من قبله -كقوم نوح وعاد وثمود وقوم لوط وأصحاب «مدين»- حال كون التوراة بصائرَ لبني إسرائيل، يبصرون بها ما ينفعهم وما يضرهم، وفيها رحمة لمن عمل بها منهم؛ لعلهم يتذكرون نِعَم الله عليهم، فيشكروه عليها، ولا يكفروه."},{"id":"3296","jozz":"20","page":"391","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"1","line_end":"2","aya_no":"44","aya_text":"وَمَا كُنتَ بِجَانِبِ ٱلۡغَرۡبِيِّ إِذۡ قَضَيۡنَآ إِلَىٰ مُوسَى ٱلۡأَمۡرَ وَمَا كُنتَ مِنَ ٱلشَّٰهِدِينَ","aya_text_emlaey":"وما كنت بجانب الغربي إذ قضينا إلى موسى الأمر وما كنت من الشاهدين","aya_tafseer":"[44] وما كنت -أيها الرسول- بجانب الجبل الغربي من موسى إذ كلَّفناه أَمْرنا ونَهْينا، وما كنت من الشاهدين لذلك، حتى يقال: إنه وصل إليك من هذا الطريق."},{"id":"3297","jozz":"20","page":"391","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"2","line_end":"4","aya_no":"45","aya_text":"وَلَٰكِنَّآ أَنشَأۡنَا قُرُونٗا فَتَطَاوَلَ عَلَيۡهِمُ ٱلۡعُمُرُۚ وَمَا كُنتَ ثَاوِيٗا فِيٓ أَهۡلِ مَدۡيَنَ تَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِنَا وَلَٰكِنَّا كُنَّا مُرۡسِلِينَ","aya_text_emlaey":"ولكنا أنشأنا قرونا فتطاول عليهم العمر وما كنت ثاويا في أهل مدين تتلو عليهم آياتنا ولكنا كنا مرسلين","aya_tafseer":"[45] ولكنا خلقنا أمماً من بعد موسى، فمكثوا زمناً طويلاً، فنسوا عهد الله، وتركوا أمره، وما كنت مقيماً في أهل «مدين» تقرأ عليهم كتابنا، فتعرف قصتهم وتخبر بها، ولكن ذلك الخبر الذي جئت به عن موسى وحي، وشاهد على رسالتك."},{"id":"3298","jozz":"20","page":"391","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"4","line_end":"6","aya_no":"46","aya_text":"وَمَا كُنتَ بِجَانِبِ ٱلطُّورِ إِذۡ نَادَيۡنَا وَلَٰكِن رَّحۡمَةٗ مِّن رَّبِّكَ لِتُنذِرَ قَوۡمٗا مَّآ أَتَىٰهُم مِّن نَّذِيرٖ مِّن قَبۡلِكَ لَعَلَّهُمۡ يَتَذَكَّرُونَ","aya_text_emlaey":"وما كنت بجانب الطور إذ نادينا ولكن رحمة من ربك لتنذر قوما ما أتاهم من نذير من قبلك لعلهم يتذكرون","aya_tafseer":"[46] وما كنت -أيها الرسول- بجانب جبل الطور حين نادينا موسى، ولم تشهد شيئاً من ذلك فتعلمه، ولكنا أرسلناك رحمة من ربك؛ لتنذر قوماً لم يأتهم مِن قبلك من نذير؛ لعلهم يتذكرون الخير الذي جئتَ به فيفعلوه، والشرَّ الذي نَهيتَ عنه فيجتنبوه."},{"id":"3299","jozz":"20","page":"391","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"7","line_end":"9","aya_no":"47","aya_text":"وَلَوۡلَآ أَن تُصِيبَهُم مُّصِيبَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ فَيَقُولُواْ رَبَّنَا لَوۡلَآ أَرۡسَلۡتَ إِلَيۡنَا رَسُولٗا فَنَتَّبِعَ ءَايَٰتِكَ وَنَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"ولولا أن تصيبهم مصيبة بما قدمت أيديهم فيقولوا ربنا لولا أرسلت إلينا رسولا فنتبع آياتك ونكون من المؤمنين","aya_tafseer":"[47] ولولا أن ينزل بهؤلاء الكفار عذاب بسبب كفرهم بربهم، فيقولوا: ربنا هلَّا أرسلت إلينا رسولاً من قبل، فنتبع آياتك المنزلة في كتابك، ونكون من المؤمنين بك."},{"id":"3300","jozz":"20","page":"391","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"9","line_end":"11","aya_no":"48","aya_text":"فَلَمَّا جَآءَهُمُ ٱلۡحَقُّ مِنۡ عِندِنَا قَالُواْ لَوۡلَآ أُوتِيَ مِثۡلَ مَآ أُوتِيَ مُوسَىٰٓۚ أَوَلَمۡ يَكۡفُرُواْ بِمَآ أُوتِيَ مُوسَىٰ مِن قَبۡلُۖ قَالُواْ سِحۡرَانِ تَظَٰهَرَا وَقَالُوٓاْ إِنَّا بِكُلّٖ كَٰفِرُونَ","aya_text_emlaey":"فلما جاءهم الحق من عندنا قالوا لولا أوتي مثل ما أوتي موسى أو لم يكفروا بما أوتي موسى من قبل قالوا سحران تظاهرا وقالوا إنا بكل كافرون","aya_tafseer":"[48] فلما جاء محمدٌ هؤلاء القوم نذيراً لهم، قالوا: هلَّا أوتي هذا الذي أُرسِل إلينا مثل ما أوتي موسى من معجزات حسية، وكتابٍ نزل جملة واحدة! قل -أيها الرسول- لهم: أو لم يكفر اليهود بما أوتي موسى من قبل؟ قالوا: في التوراة والقرآن سِحْران تعاونا في سحرهما، وقالوا: نحن بكل منهما كافرون."},{"id":"3301","jozz":"20","page":"391","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"12","line_end":"13","aya_no":"49","aya_text":"قُلۡ فَأۡتُواْ بِكِتَٰبٖ مِّنۡ عِندِ ٱللَّهِ هُوَ أَهۡدَىٰ مِنۡهُمَآ أَتَّبِعۡهُ إِن كُنتُمۡ صَٰدِقِينَ","aya_text_emlaey":"قل فأتوا بكتاب من عند الله هو أهدى منهما أتبعه إن كنتم صادقين","aya_tafseer":"[49] قل -أيها الرسول- لهؤلاء: فأتوا بكتاب من عند الله هو أقوم من التوراة والقرآن أتبعه، إن كنتم صادقين في زعمكم."},{"id":"3302","jozz":"20","page":"391","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"13","line_end":"15","aya_no":"50","aya_text":"فَإِن لَّمۡ يَسۡتَجِيبُواْ لَكَ فَٱعۡلَمۡ أَنَّمَا يَتَّبِعُونَ أَهۡوَآءَهُمۡۚ وَمَنۡ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَيۡرِ هُدٗى مِّنَ ٱللَّهِۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ","aya_text_emlaey":"فإن لم يستجيبوا لك فاعلم أنما يتبعون أهواءهم ومن أضل ممن اتبع هواه بغير هدى من الله إن الله لا يهدي القوم الظالمين","aya_tafseer":"[50] فإن لم يستجيبوا لك بالإتيان بالكتاب، ولم تبق لهم حجة، فاعلم أنما يتبعون أهواءهم، ولا أحد أكثر ضلالاً ممن اتبع هواه بغير هدى من الله. إن الله لا يوفِّق لإصابة الحق القوم الظالمين الذين خالفوا أمر الله، وتجاوزوا حدوده."},{"id":"3303","jozz":"20","page":"392","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"1","line_end":"1","aya_no":"51","aya_text":"۞ وَلَقَدۡ وَصَّلۡنَا لَهُمُ ٱلۡقَوۡلَ لَعَلَّهُمۡ يَتَذَكَّرُونَ","aya_text_emlaey":"ولقد وصلنا لهم القول لعلهم يتذكرون","aya_tafseer":"[51] ولقد فصَّلنا وبيَّنا القرآن رحمة بقومك أيها الرسول؛ لعلهم يتذكرون، فيتعظوا به."},{"id":"3304","jozz":"20","page":"392","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"1","line_end":"2","aya_no":"52","aya_text":"ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ مِن قَبۡلِهِۦ هُم بِهِۦ يُؤۡمِنُونَ","aya_text_emlaey":"الذين آتيناهم الكتاب من قبله هم به يؤمنون","aya_tafseer":"[52] الذين آتيناهم الكتاب من قبل القرآن -وهم اليهود والنصارى الذين لم يبدِّلوا- يؤمنون بالقرآن وبمحمد عليه الصلاة والسلام."},{"id":"3305","jozz":"20","page":"392","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"2","line_end":"4","aya_no":"53","aya_text":"وَإِذَا يُتۡلَىٰ عَلَيۡهِمۡ قَالُوٓاْ ءَامَنَّا بِهِۦٓ إِنَّهُ ٱلۡحَقُّ مِن رَّبِّنَآ إِنَّا كُنَّا مِن قَبۡلِهِۦ مُسۡلِمِينَ","aya_text_emlaey":"وإذا يتلى عليهم قالوا آمنا به إنه الحق من ربنا إنا كنا من قبله مسلمين","aya_tafseer":"[53] وإذا يتلى هذا القرآن على الذين آتيناهم الكتاب، قالوا: صدَّقنا به، وعملنا بما فيه، إنه الحق من عند ربنا، إنا كنا من قبل نزوله مسلمين موحدين، فدين الله واحد، وهو الإسلام."},{"id":"3306","jozz":"20","page":"392","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"4","line_end":"5","aya_no":"54","aya_text":"أُوْلَٰٓئِكَ يُؤۡتَوۡنَ أَجۡرَهُم مَّرَّتَيۡنِ بِمَا صَبَرُواْ وَيَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّيِّئَةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ","aya_text_emlaey":"أولئك يؤتون أجرهم مرتين بما صبروا ويدرءون بالحسنة السيئة ومما رزقناهم ينفقون","aya_tafseer":"[54] هؤلاء الذين تقدَّمَتْ صفتُهم يُؤتَوْن ثواب عملهم مرتين: على الإيمان بكتابهم، وعلى إيمانهم بالقرآن بما صبروا، ومن أوصافهم أنهم يدفعون السيئة بالحسنة، ومما رزقناهم ينفقون في سبيل الخير والبر"},{"id":"3307","jozz":"20","page":"392","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"5","line_end":"7","aya_no":"55","aya_text":"وَإِذَا سَمِعُواْ ٱللَّغۡوَ أَعۡرَضُواْ عَنۡهُ وَقَالُواْ لَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡ سَلَٰمٌ عَلَيۡكُمۡ لَا نَبۡتَغِي ٱلۡجَٰهِلِينَ","aya_text_emlaey":"وإذا سمعوا اللغو أعرضوا عنه وقالوا لنا أعمالنا ولكم أعمالكم سلام عليكم لا نبتغي الجاهلين","aya_tafseer":"[55] . وإذا سمع هؤلاء القوم الباطل من القول لم يُصْغوا إليه، وقالوا: لنا أعمالنا لا نحيد عنها، ولكم أعمالكم ووزرها عليكم، فنحن لا نَشْغَل أنفسنا بالرد عليكم، ولا تسمعون منَّا إلا الخير، ولا نخاطبكم بمقتضى جهلكم؛ لأننا لا نريد طريق الجاهلين ولا نحبها. وهذا من خير ما يقوله الدعاة إلى الله."},{"id":"3308","jozz":"20","page":"392","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"7","line_end":"8","aya_no":"56","aya_text":"إِنَّكَ لَا تَهۡدِي مَنۡ أَحۡبَبۡتَ وَلَٰكِنَّ ٱللَّهَ يَهۡدِي مَن يَشَآءُۚ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ","aya_text_emlaey":"إنك لا تهدي من أحببت ولكن الله يهدي من يشاء وهو أعلم بالمهتدين","aya_tafseer":"[56] إنك -أيها الرسول- لا تهدي هداية توفيق مَن أحببت هدايته، ولكن ذلك بيد الله يهدي مَن يشاء أن يهديه للإيمان، ويوفقه إليه، وهو أعلم بمن يصلح للهداية فيهديه."},{"id":"3309","jozz":"20","page":"392","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"9","line_end":"11","aya_no":"57","aya_text":"وَقَالُوٓاْ إِن نَّتَّبِعِ ٱلۡهُدَىٰ مَعَكَ نُتَخَطَّفۡ مِنۡ أَرۡضِنَآۚ أَوَلَمۡ نُمَكِّن لَّهُمۡ حَرَمًا ءَامِنٗا يُجۡبَىٰٓ إِلَيۡهِ ثَمَرَٰتُ كُلِّ شَيۡءٖ رِّزۡقٗا مِّن لَّدُنَّا وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ","aya_text_emlaey":"وقالوا إن نتبع الهدى معك نتخطف من أرضنا أو لم نمكن لهم حرما آمنا يجبى إليه ثمرات كل شيء رزقا من لدنا ولكن أكثرهم لا يعلمون","aya_tafseer":"[57] وقال كفار «مكة»: إن نتبع الحق الذي جئتنا به، ونتبرأ من الأولياء والآلهة، نُتَخَطَّفْ من أرضنا بالقتل والأسر ونهب الأموال، أولم نجعلهم متمكنين في بلد آمن، حرَّمنا على الناس سفك الدماء فيه، يُجلب إليه ثمرات كل شيء رزقاً مِن لدنا؟ ولكن أكثر هؤلاء المشركين لا يعلمون قَدْر هذه النعم عليهم، فيشكروا مَن أنعم عليهم بها ويطيعوه."},{"id":"3310","jozz":"20","page":"392","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"11","line_end":"13","aya_no":"58","aya_text":"وَكَمۡ أَهۡلَكۡنَا مِن قَرۡيَةِۭ بَطِرَتۡ مَعِيشَتَهَاۖ فَتِلۡكَ مَسَٰكِنُهُمۡ لَمۡ تُسۡكَن مِّنۢ بَعۡدِهِمۡ إِلَّا قَلِيلٗاۖ وَكُنَّا نَحۡنُ ٱلۡوَٰرِثِينَ","aya_text_emlaey":"وكم أهلكنا من قرية بطرت معيشتها فتلك مساكنهم لم تسكن من بعدهم إلا قليلا وكنا نحن الوارثين","aya_tafseer":"[58] وكثير من أهل القرى أهلكناهم حين ألْهَتْهم معيشتهم عن الإيمان بالرسل، فكفروا وطغَوْا، فتلك مساكنهم لم تُسكن من بعدهم إلا قليلاً منها، وكنا نحن الوارثين للعباد نميتهم، ثم يرجعون إلينا، فنجازيهم بأعمالهم."},{"id":"3311","jozz":"20","page":"392","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"13","line_end":"15","aya_no":"59","aya_text":"وَمَا كَانَ رَبُّكَ مُهۡلِكَ ٱلۡقُرَىٰ حَتَّىٰ يَبۡعَثَ فِيٓ أُمِّهَا رَسُولٗا يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِنَاۚ وَمَا كُنَّا مُهۡلِكِي ٱلۡقُرَىٰٓ إِلَّا وَأَهۡلُهَا ظَٰلِمُونَ","aya_text_emlaey":"وما كان ربك مهلك القرى حتى يبعث في أمها رسولا يتلو عليهم آياتنا وما كنا مهلكي القرى إلا وأهلها ظالمون","aya_tafseer":"[59] وما كان ربك -أيها الرسول- مهلك القرى التي حول «مكة» في زمانك حتى يبعث في أمها -وهي «مكة»- رسولاً، يتلو عليهم آياتنا، وما كنا مهلكي القرى إلا وأهلها ظالمون لأنفسهم بكفرهم بالله ومعصيته، فهم بذلك مستحقون للعقوبة والنكال."},{"id":"3312","jozz":"20","page":"393","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"1","line_end":"2","aya_no":"60","aya_text":"وَمَآ أُوتِيتُم مِّن شَيۡءٖ فَمَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَزِينَتُهَاۚ وَمَا عِندَ ٱللَّهِ خَيۡرٞ وَأَبۡقَىٰٓۚ أَفَلَا تَعۡقِلُونَ","aya_text_emlaey":"وما أوتيتم من شيء فمتاع الحياة الدنيا وزينتها وما عند الله خير وأبقى أفلا تعقلون","aya_tafseer":"[60] وما أُعطيتم -أيها الناس- من شيء من الأموال والأولاد، فإنما هو متاع تتمتعون به في هذه الحياة الدنيا، وزينة يُتزيَّن بها، وما عند الله لأهل طاعته وولايته خير وأبقى؛ لأنه دائم لا نفاد له، أفلا تكون لكم عقول -أيها القوم- تتدبرون بها، فتعرفون الخير من الشر؟"},{"id":"3313","jozz":"20","page":"393","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"2","line_end":"4","aya_no":"61","aya_text":"أَفَمَن وَعَدۡنَٰهُ وَعۡدًا حَسَنٗا فَهُوَ لَٰقِيهِ كَمَن مَّتَّعۡنَٰهُ مَتَٰعَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا ثُمَّ هُوَ يَوۡمَ ٱلۡقِيَٰمَةِ مِنَ ٱلۡمُحۡضَرِينَ","aya_text_emlaey":"أفمن وعدناه وعدا حسنا فهو لاقيه كمن متعناه متاع الحياة الدنيا ثم هو يوم القيامة من المحضرين","aya_tafseer":"[61] أفمَن وعدناه مِن خَلْقنا على طاعته إيانا الجنة، فهو ملاقٍ ما وُعِدَ، وصائر إليه، كمن متعناه في الحياة الدنيا متاعها، فتمتع به، وآثر لذة عاجلة على آجلة، ثم هو يوم القيامة من المحضرين للحساب والجزاء؟ لا يستوي الفريقان، فليختر العاقل لنفسه ما هو أولى بالاختيار، وهو طاعة الله وابتغاء مرضاته."},{"id":"3314","jozz":"20","page":"393","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"4","line_end":"5","aya_no":"62","aya_text":"وَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ أَيۡنَ شُرَكَآءِيَ ٱلَّذِينَ كُنتُمۡ تَزۡعُمُونَ","aya_text_emlaey":"ويوم يناديهم فيقول أين شركائي الذين كنتم تزعمون","aya_tafseer":"[62] ويوم ينادي الله عز وجل الذين أشركوا به الأولياء والأوثان في الدنيا، فيقول لهم: أين شركائي الذين كنتم تزعمون أنهم لي شركاء؟"},{"id":"3315","jozz":"20","page":"393","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"5","line_end":"7","aya_no":"63","aya_text":"قَالَ ٱلَّذِينَ حَقَّ عَلَيۡهِمُ ٱلۡقَوۡلُ رَبَّنَا هَٰٓؤُلَآءِ ٱلَّذِينَ أَغۡوَيۡنَآ أَغۡوَيۡنَٰهُمۡ كَمَا غَوَيۡنَاۖ تَبَرَّأۡنَآ إِلَيۡكَۖ مَا كَانُوٓاْ إِيَّانَا يَعۡبُدُونَ","aya_text_emlaey":"قال الذين حق عليهم القول ربنا هؤلاء الذين أغوينا أغويناهم كما غوينا تبرأنا إليك ما كانوا إيانا يعبدون","aya_tafseer":"[63] قال الذين حقَّ عليهم العذاب، وهم دعاة الكفر: ربنا هؤلاء الذين أضللنا، أضللناهم كما ضللنا، تبرأنا إليك مِن ولايتهم ونصرتهم، ما كانوا إيانا يعبدون، وإنما كانوا يعبدون الشياطين."},{"id":"3316","jozz":"20","page":"393","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"7","line_end":"8","aya_no":"64","aya_text":"وَقِيلَ ٱدۡعُواْ شُرَكَآءَكُمۡ فَدَعَوۡهُمۡ فَلَمۡ يَسۡتَجِيبُواْ لَهُمۡ وَرَأَوُاْ ٱلۡعَذَابَۚ لَوۡ أَنَّهُمۡ كَانُواْ يَهۡتَدُونَ","aya_text_emlaey":"وقيل ادعوا شركاءكم فدعوهم فلم يستجيبوا لهم ورأوا العذاب لو أنهم كانوا يهتدون","aya_tafseer":"[64] وقيل للمشركين بالله يوم القيامة: ادعوا شركاءكم الذين كنتم تعبدونهم من دون الله، فدعَوهم فلم يستجيبوا لهم، وعاينوا العذاب، لو أنهم كانوا في الدنيا مهتدين للحق لما عُذِّبوا."},{"id":"3317","jozz":"20","page":"393","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"9","line_end":"9","aya_no":"65","aya_text":"وَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ مَاذَآ أَجَبۡتُمُ ٱلۡمُرۡسَلِينَ","aya_text_emlaey":"ويوم يناديهم فيقول ماذا أجبتم المرسلين","aya_tafseer":"[65] ويوم ينادي الله هؤلاء المشركين، فيقول: بأيِّ شيء أجبتم المرسلين فيما أرسلناهم به إليكم؟"},{"id":"3318","jozz":"20","page":"393","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"9","line_end":"10","aya_no":"66","aya_text":"فَعَمِيَتۡ عَلَيۡهِمُ ٱلۡأَنۢبَآءُ يَوۡمَئِذٖ فَهُمۡ لَا يَتَسَآءَلُونَ","aya_text_emlaey":"فعميت عليهم الأنباء يومئذ فهم لا يتساءلون","aya_tafseer":"[66] فخفيت عليهم الحجج، فلم يَدْروا ما يحتجون به، فهم لا يسأل بعضهم بعضاً عما يحتجون به سؤال انتفاع."},{"id":"3319","jozz":"20","page":"393","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"10","line_end":"11","aya_no":"67","aya_text":"فَأَمَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحٗا فَعَسَىٰٓ أَن يَكُونَ مِنَ ٱلۡمُفۡلِحِينَ","aya_text_emlaey":"فأما من تاب وآمن وعمل صالحا فعسى أن يكون من المفلحين","aya_tafseer":"[67] فأما من تاب من المشركين، وأخلص لله العبادة، وعمل بما أمره الله به ورسوله، فهو من الفائزين في الدارين."},{"id":"3320","jozz":"20","page":"393","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"12","line_end":"13","aya_no":"68","aya_text":"وَرَبُّكَ يَخۡلُقُ مَا يَشَآءُ وَيَخۡتَارُۗ مَا كَانَ لَهُمُ ٱلۡخِيَرَةُۚ سُبۡحَٰنَ ٱللَّهِ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ","aya_text_emlaey":"وربك يخلق ما يشاء ويختار ما كان لهم الخيرة سبحان الله وتعالى عما يشركون","aya_tafseer":"[68] وربك يخلق ما يشاء أن يخلقه، ويصطفي لولايته مَن يشاء من خلقه، وليس لأحد من الأمر والاختيار شيء، وإنما ذلك لله وحده سبحانه، تعالى وتنزَّه عن شركهم."},{"id":"3321","jozz":"20","page":"393","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"13","line_end":"14","aya_no":"69","aya_text":"وَرَبُّكَ يَعۡلَمُ مَا تُكِنُّ صُدُورُهُمۡ وَمَا يُعۡلِنُونَ","aya_text_emlaey":"وربك يعلم ما تكن صدورهم وما يعلنون","aya_tafseer":"[69] وربك يعلم ما تُخفي صدور خلقه وما يظهرونه."},{"id":"3322","jozz":"20","page":"393","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"14","line_end":"15","aya_no":"70","aya_text":"وَهُوَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ لَهُ ٱلۡحَمۡدُ فِي ٱلۡأُولَىٰ وَٱلۡأٓخِرَةِۖ وَلَهُ ٱلۡحُكۡمُ وَإِلَيۡهِ تُرۡجَعُونَ","aya_text_emlaey":"وهو الله لا إله إلا هو له الحمد في الأولى والآخرة وله الحكم وإليه ترجعون","aya_tafseer":"[70] وهو الله الذي لا معبود بحق سواه، له الثناء الجميل والشكر في الدنيا والآخرة، وله الحكم بين خلقه، وإليه تُرَدُّون بعد مماتكم للحساب والجزاء."},{"id":"3323","jozz":"20","page":"394","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"1","line_end":"2","aya_no":"71","aya_text":"قُلۡ أَرَءَيۡتُمۡ إِن جَعَلَ ٱللَّهُ عَلَيۡكُمُ ٱلَّيۡلَ سَرۡمَدًا إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ مَنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِضِيَآءٍۚ أَفَلَا تَسۡمَعُونَ","aya_text_emlaey":"قل أرأيتم إن جعل الله عليكم الليل سرمدا إلى يوم القيامة من إله غير الله يأتيكم بضياء أفلا تسمعون","aya_tafseer":"[71] قل -أيها الرسول-: أخبروني -أيها الناس- إن جعل الله عليكم الليل دائماً إلى يوم القيامة، مَن إله غير الله يأتيكم بضياء تستضيئون به؟ أفلا تسمعون سماع فهم وقَبول؟"},{"id":"3324","jozz":"20","page":"394","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"3","line_end":"5","aya_no":"72","aya_text":"قُلۡ أَرَءَيۡتُمۡ إِن جَعَلَ ٱللَّهُ عَلَيۡكُمُ ٱلنَّهَارَ سَرۡمَدًا إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ مَنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِلَيۡلٖ تَسۡكُنُونَ فِيهِۚ أَفَلَا تُبۡصِرُونَ","aya_text_emlaey":"قل أرأيتم إن جعل الله عليكم النهار سرمدا إلى يوم القيامة من إله غير الله يأتيكم بليل تسكنون فيه أفلا تبصرون","aya_tafseer":"[72] قل لهم: أخبروني إن جعل الله عليكم النهار دائماً إلى يوم القيامة، مَن إله غير الله يأتيكم بليل تستقرون وتهدؤون فيه؟ أفلا ترون بأبصاركم اختلاف الليل والنهار؟"},{"id":"3325","jozz":"20","page":"394","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"5","line_end":"7","aya_no":"73","aya_text":"وَمِن رَّحۡمَتِهِۦ جَعَلَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ لِتَسۡكُنُواْ فِيهِ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ","aya_text_emlaey":"ومن رحمته جعل لكم الليل والنهار لتسكنوا فيه ولتبتغوا من فضله ولعلكم تشكرون","aya_tafseer":"[73] ومن رحمته بكم -أيها الناس- أن جعل لكم الليل والنهار فخالف بينهما، فجعل هذا الليل ظلاماً؛ لتستقروا فيه وترتاح أبدانكم، وجعل لكم النهار ضياءً؛ لتطلبوا فيه معايشكم، ولتشكروا له على إنعامه عليكم بذلك."},{"id":"3326","jozz":"20","page":"394","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"7","line_end":"8","aya_no":"74","aya_text":"وَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ أَيۡنَ شُرَكَآءِيَ ٱلَّذِينَ كُنتُمۡ تَزۡعُمُونَ","aya_text_emlaey":"ويوم يناديهم فيقول أين شركائي الذين كنتم تزعمون","aya_tafseer":"[74] ويوم ينادي الله هؤلاء المشركين، فيقول لهم: أين شركائي الذين كنتم تزعمون في الدنيا أنهم شركائي؟"},{"id":"3327","jozz":"20","page":"394","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"8","line_end":"10","aya_no":"75","aya_text":"وَنَزَعۡنَا مِن كُلِّ أُمَّةٖ شَهِيدٗا فَقُلۡنَا هَاتُواْ بُرۡهَٰنَكُمۡ فَعَلِمُوٓاْ أَنَّ ٱلۡحَقَّ لِلَّهِ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ","aya_text_emlaey":"ونـزعنا من كل أمة شهيدا فقلنا هاتوا برهانكم فعلموا أن الحق لله وضل عنهم ما كانوا يفترون","aya_tafseer":"[75] ونزعنا من كل أمة من الأمم المكذبة شهيداً -وهو نبيُّهم-، يشهد على ما جرى في الدنيا من شركهم وتكذيبهم لرسلهم، فقلنا لتلك الأمم التي كذبت رسلها وما جاءت به من عند الله: هاتوا حجتكم على ما أشركتم مع الله، فعلموا حينئذ أن الحجة البالغة لله عليهم، وأن الحق لله، وذهب عنهم ما كانوا يفترون على ربهم، فلم ينفعهم ذلك، بل ضرَّهم وأوردهم نار جهنم."},{"id":"3328","jozz":"20","page":"394","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"10","line_end":"13","aya_no":"76","aya_text":"۞ إِنَّ قَٰرُونَ كَانَ مِن قَوۡمِ مُوسَىٰ فَبَغَىٰ عَلَيۡهِمۡۖ وَءَاتَيۡنَٰهُ مِنَ ٱلۡكُنُوزِ مَآ إِنَّ مَفَاتِحَهُۥ لَتَنُوٓأُ بِٱلۡعُصۡبَةِ أُوْلِي ٱلۡقُوَّةِ إِذۡ قَالَ لَهُۥ قَوۡمُهُۥ لَا تَفۡرَحۡۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡفَرِحِينَ","aya_text_emlaey":"إن قارون كان من قوم موسى فبغى عليهم وآتيناه من الكنوز ما إن مفاتحه لتنوأ بالعصبة أولي القوة إذ قال له قومه لا تفرح إن الله لا يحب الفرحين","aya_tafseer":"[76] إن قارون كان من قوم موسى -عليه الصلاة والسلام- فتجاوز حدَّه في الكِبْر والتجبر عليهم، وآتينا قارون من كنوز الأموال شيئاً عظيماً، حتى إنَّ مفاتيحَ خزائنِه لَيثقل حِمْلها على العدد الكثير من الأقوياء، إذ قال له قومه: لا تبطر فرحاً بما أنت فيه من المال، إن الله لا يحب مِن خلقه البَطِرين الذين لا يشكرون لله تعالى ما أعطاهم."},{"id":"3329","jozz":"20","page":"394","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"13","line_end":"15","aya_no":"77","aya_text":"وَٱبۡتَغِ فِيمَآ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلۡأٓخِرَةَۖ وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنۡيَاۖ وَأَحۡسِن كَمَآ أَحۡسَنَ ٱللَّهُ إِلَيۡكَۖ وَلَا تَبۡغِ ٱلۡفَسَادَ فِي ٱلۡأَرۡضِۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُفۡسِدِينَ","aya_text_emlaey":"وابتغ فيما آتاك الله الدار الآخرة ولا تنس نصيبك من الدنيا وأحسن كما أحسن الله إليك ولا تبغ الفساد في الأرض إن الله لا يحب المفسدين","aya_tafseer":"[77] والتمس فيما آتاك الله من الأموال ثواب الدار الآخرة، بالعمل فيها بطاعة الله في الدنيا، ولا تترك حظك من الدنيا، بأن تتمتع فيها بالحلال دون إسراف، وأحسن إلى الناس بالصدقة، كما أحسن الله إليك بهذه الأموال الكثيرة، ولا تلتمس ما حرَّم الله عليك من الفساد في الأرض والبغي على قومك، إن الله لا يحب المفسدين، وسيجازيهم على سوء صنيعهم."},{"id":"3330","jozz":"20","page":"395","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"1","line_end":"3","aya_no":"78","aya_text":"قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلۡمٍ عِندِيٓۚ أَوَلَمۡ يَعۡلَمۡ أَنَّ ٱللَّهَ قَدۡ أَهۡلَكَ مِن قَبۡلِهِۦ مِنَ ٱلۡقُرُونِ مَنۡ هُوَ أَشَدُّ مِنۡهُ قُوَّةٗ وَأَكۡثَرُ جَمۡعٗاۚ وَلَا يُسۡـَٔلُ عَن ذُنُوبِهِمُ ٱلۡمُجۡرِمُونَ","aya_text_emlaey":"قال إنما أوتيته على علم عندي أو لم يعلم أن الله قد أهلك من قبله من القرون من هو أشد منه قوة وأكثر جمعا ولا يسأل عن ذنوبهم المجرمون","aya_tafseer":"[78] قال قارون لقومه الذين وعظوه: إنما أُعطيتُ هذه الكنوز بما عندي من العلم والقدرة، أولم يعلم قارون أن الله قد أهلك مِن قبله من الأمم مَن هو أشد منه بطشاً، وأكثر جمعاً للأموال؟ ولا يُسأل عن ذنوبهم المجرمون؛ لعلم الله تعالى بها، إنما يُسْألون سؤال توبيخ وتقرير، ويعاقبهم الله على ما علمه منهم."},{"id":"3331","jozz":"20","page":"395","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"3","line_end":"5","aya_no":"79","aya_text":"فَخَرَجَ عَلَىٰ قَوۡمِهِۦ فِي زِينَتِهِۦۖ قَالَ ٱلَّذِينَ يُرِيدُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا يَٰلَيۡتَ لَنَا مِثۡلَ مَآ أُوتِيَ قَٰرُونُ إِنَّهُۥ لَذُو حَظٍّ عَظِيمٖ","aya_text_emlaey":"فخرج على قومه في زينته قال الذين يريدون الحياة الدنيا ياليت لنا مثل ما أوتي قارون إنه لذو حظ عظيم","aya_tafseer":"[79] فخرج قارون على قومه في زينته، مريداً بذلك إظهار عظمته وكثرة أمواله، وحين رآه الذين يريدون زينة الحياة الدنيا قالوا: يا ليت لنا مثل ما أُعطي قارون من المال والزينة والجاه، إن قارون لذو نصيب عظيم من الدنيا."},{"id":"3332","jozz":"20","page":"395","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"5","line_end":"7","aya_no":"80","aya_text":"وَقَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ وَيۡلَكُمۡ ثَوَابُ ٱللَّهِ خَيۡرٞ لِّمَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗاۚ وَلَا يُلَقَّىٰهَآ إِلَّا ٱلصَّٰبِرُونَ","aya_text_emlaey":"وقال الذين أوتوا العلم ويلكم ثواب الله خير لمن آمن وعمل صالحا ولا يلقاها إلا الصابرون","aya_tafseer":"[80] وقال الذين أوتوا العلم بالله وشرعه وعرفوا حقائق الأمور للذين قالوا: يا ليت لنا مثل ما أوتي قارون: ويلكم اتقوا الله وأطيعوه، ثوابُ الله لمن آمن به وبرسله، وعمل الأعمال الصالحة، خيرٌ مما أوتي قارون، ولا يَتَقَبَّل هذه النصيحة ويوفَّق إليها ويعمل بها إلا مَن يجاهد نفسه، ويصبر على طاعة ربه، ويجتنب معاصيه."},{"id":"3333","jozz":"20","page":"395","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"7","line_end":"9","aya_no":"81","aya_text":"فَخَسَفۡنَا بِهِۦ وَبِدَارِهِ ٱلۡأَرۡضَ فَمَا كَانَ لَهُۥ مِن فِئَةٖ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مِنَ ٱلۡمُنتَصِرِينَ","aya_text_emlaey":"فخسفنا به وبداره الأرض فما كان له من فئة ينصرونه من دون الله وما كان من المنتصرين","aya_tafseer":"[81] فخسفنا بقارون وبداره الأرض، فما كان له من جند ينصرونه من دون الله، وما كان ممتنعاً من الله إذا أحلَّ به نقمته."},{"id":"3334","jozz":"20","page":"395","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"9","line_end":"12","aya_no":"82","aya_text":"وَأَصۡبَحَ ٱلَّذِينَ تَمَنَّوۡاْ مَكَانَهُۥ بِٱلۡأَمۡسِ يَقُولُونَ وَيۡكَأَنَّ ٱللَّهَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ مِنۡ عِبَادِهِۦ وَيَقۡدِرُۖ لَوۡلَآ أَن مَّنَّ ٱللَّهُ عَلَيۡنَا لَخَسَفَ بِنَاۖ وَيۡكَأَنَّهُۥ لَا يُفۡلِحُ ٱلۡكَٰفِرُونَ","aya_text_emlaey":"وأصبح الذين تمنوا مكانه بالأمس يقولون ويكأن الله يبسط الرزق لمن يشاء من عباده ويقدر لولا أن من الله علينا لخسف بنا ويكأنه لا يفلح الكافرون","aya_tafseer":"[82] وصار الذين تمنوا حاله بالأمس يقولون متوجعين ومعتبرين وخائفين من وقوع العذاب بهم: إن الله يوسِّع الرزق لمن يشاء من عباده، ويضيِّق على مَن يشاء منهم، لولا أن الله منَّ علينا فلم يعاقبنا على ما قلنا لَخسف بنا كما فعل بقارون، ألم تعلم أنه لا يفلح الكافرون، لا في الدنيا ولا في الآخرة؟"},{"id":"3335","jozz":"20","page":"395","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"12","line_end":"13","aya_no":"83","aya_text":"تِلۡكَ ٱلدَّارُ ٱلۡأٓخِرَةُ نَجۡعَلُهَا لِلَّذِينَ لَا يُرِيدُونَ عُلُوّٗا فِي ٱلۡأَرۡضِ وَلَا فَسَادٗاۚ وَٱلۡعَٰقِبَةُ لِلۡمُتَّقِينَ","aya_text_emlaey":"تلك الدار الآخرة نجعلها للذين لا يريدون علوا في الأرض ولا فسادا والعاقبة للمتقين","aya_tafseer":"[83] تلك الدار الآخرة نجعل نعيمها للذين لا يريدون تكبراً عن الحق في الأرض ولا فساداً فيها. والعاقبة المحمودة -وهي الجنة- لمن اتقى عذاب الله وعمل الطاعات، وترك المحرمات."},{"id":"3336","jozz":"20","page":"395","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"14","line_end":"15","aya_no":"84","aya_text":"مَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ خَيۡرٞ مِّنۡهَاۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجۡزَى ٱلَّذِينَ عَمِلُواْ ٱلسَّيِّـَٔاتِ إِلَّا مَا كَانُواْ يَعۡمَلُونَ","aya_text_emlaey":"من جاء بالحسنة فله خير منها ومن جاء بالسيئة فلا يجزى الذين عملوا السيئات إلا ما كانوا يعملون","aya_tafseer":"[84] من جاء يوم القيامة بإخلاص التوحيد لله وبالأعمال الصالحة وَفْق ما شرع الله، فله أجر عظيم خير من ذلك، وذلك الخير هو الجنة والنعيم الدائم، ومن جاء بالأعمال السيئة، فلا يُجْزى الذين عملوا السيئات على أعمالهم إلا بما كانوا يعملون."},{"id":"3337","jozz":"20","page":"396","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"1","line_end":"2","aya_no":"85","aya_text":"إِنَّ ٱلَّذِي فَرَضَ عَلَيۡكَ ٱلۡقُرۡءَانَ لَرَآدُّكَ إِلَىٰ مَعَادٖۚ قُل رَّبِّيٓ أَعۡلَمُ مَن جَآءَ بِٱلۡهُدَىٰ وَمَنۡ هُوَ فِي ضَلَٰلٖ مُّبِينٖ","aya_text_emlaey":"إن الذي فرض عليك القرآن لرادك إلى معاد قل ربي أعلم من جاء بالهدى ومن هو في ضلال مبين","aya_tafseer":"[85] إن الذي أنزل عليك -أيها الرسول- القرآن، وفرض عليك تبليغه والتمسُّك به، لمُرْجعك إلى الموضع الذي خرجت منه، وهو «مكة»، قل أيها الرسول لهؤلاء المشركين: ربي أعلم مَن جاء بالهدى، ومن هو في ذهابٍ واضحٍ عن الحق."},{"id":"3338","jozz":"20","page":"396","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"2","line_end":"4","aya_no":"86","aya_text":"وَمَا كُنتَ تَرۡجُوٓاْ أَن يُلۡقَىٰٓ إِلَيۡكَ ٱلۡكِتَٰبُ إِلَّا رَحۡمَةٗ مِّن رَّبِّكَۖ فَلَا تَكُونَنَّ ظَهِيرٗا لِّلۡكَٰفِرِينَ","aya_text_emlaey":"وما كنت ترجو أن يلقى إليك الكتاب إلا رحمة من ربك فلا تكونن ظهيرا للكافرين","aya_tafseer":"[86] وما كنت -أيها الرسول- تُؤمِّل نزول القرآن عليك، لكن الله سبحانه وتعالى رحمك فأنزله عليك، فاشكر لله تعالى على نِعَمه، ولا تكوننَّ عوناً لأهل الشرك والضلال."},{"id":"3339","jozz":"20","page":"396","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"4","line_end":"6","aya_no":"87","aya_text":"وَلَا يَصُدُّنَّكَ عَنۡ ءَايَٰتِ ٱللَّهِ بَعۡدَ إِذۡ أُنزِلَتۡ إِلَيۡكَۖ وَٱدۡعُ إِلَىٰ رَبِّكَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ","aya_text_emlaey":"ولا يصدنك عن آيات الله بعد إذ أنـزلت إليك وادع إلى ربك ولا تكونن من المشركين","aya_tafseer":"[87] ولا يصرفَنَّك هؤلاء المشركون عن تبليغ آيات ربك وحججه، بعد أن أنزلها إليك، وبلِّغ رسالة ربك، ولا تكونن من المشركين في شيء."},{"id":"3340","jozz":"20","page":"396","sura_no":"28","sura_name_en":"Al-Qaṣaṣ","sura_name_ar":"القَصَص ","line_start":"6","line_end":"7","aya_no":"88","aya_text":"وَلَا تَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَۘ لَآ إِلَٰهَ إِلَّا هُوَۚ كُلُّ شَيۡءٍ هَالِكٌ إِلَّا وَجۡهَهُۥۚ لَهُ ٱلۡحُكۡمُ وَإِلَيۡهِ تُرۡجَعُونَ","aya_text_emlaey":"ولا تدع مع الله إلها آخر لا إله إلا هو كل شيء هالك إلا وجهه له الحكم وإليه ترجعون","aya_tafseer":"[88] ولا تعبد مع الله معبوداً آخر؛ فلا معبود بحق إلا الله، كل شيء هالك وفانٍ إلا وجهه، له الحكم، وإليه ترجعون من بعد موتكم للحساب والجزاء. وفي هذه الآية إثبات صفة الوجه لله تعالى كما يليق بكماله وعظمة جلاله."}]
